-- ============================================================
-- CAMPAIGN SEAT
-- RECURRING TASK RUNTIME
-- ============================================================
--
-- Design:
-- 1. Existing task = first occurrence / template source.
-- 2. Recurrence rule snapshots task fields + checklist.
-- 3. Future tasks are generated by pg_cron.
-- 4. Generated tasks are idempotent.
-- 5. Existing generated/completed tasks are never mutated.
-- 6. Dependencies intentionally do NOT copy.
-- ============================================================


-- ============================================================
-- RECURRENCE RULES
-- ============================================================

create table if not exists
public.task_recurrence_rules (
  id uuid primary key
    default gen_random_uuid(),

  workspace_id uuid not null
    references public.workspaces(id)
    on delete cascade,

  created_by uuid not null
    references public.profiles(id)
    on delete restrict,

  template_task_id uuid,

  title text not null,

  description text,

  category text not null
    default 'General',

  priority text not null
    default 'normal',

  visibility text not null
    default 'workspace',

  tags text[] not null
    default '{}'::text[],

  estimated_minutes integer,

  assigned_to uuid
    references public.profiles(id)
    on delete set null,

  checklist_template jsonb not null
    default '[]'::jsonb,

  recurrence_unit text not null,

  interval_count integer not null
    default 1,

  schedule_timezone text not null
    default 'America/New_York',

  start_at timestamptz not null,

  end_at timestamptz,

  next_occurrence_at timestamptz not null,

  last_occurrence_at timestamptz,

  is_enabled boolean not null
    default true,

  created_at timestamptz not null
    default now(),

  updated_at timestamptz not null
    default now(),

  constraint
    task_recurrence_rules_title_valid
    check (
      length(btrim(title))
        between 1 and 180
    ),

  constraint
    task_recurrence_rules_description_valid
    check (
      description is null
      or length(description) <= 5000
    ),

  constraint
    task_recurrence_rules_unit_valid
    check (
      recurrence_unit in (
        'day',
        'week',
        'month'
      )
    ),

  constraint
    task_recurrence_rules_interval_valid
    check (
      interval_count
        between 1 and 365
    ),

  constraint
    task_recurrence_rules_estimate_valid
    check (
      estimated_minutes is null
      or estimated_minutes
        between 1 and 10080
    ),

  constraint
    task_recurrence_rules_checklist_valid
    check (
      jsonb_typeof(
        checklist_template
      ) = 'array'
    ),

  constraint
    task_recurrence_rules_end_valid
    check (
      end_at is null
      or end_at >= start_at
    ),

  constraint
    task_recurrence_rules_next_valid
    check (
      next_occurrence_at >=
        start_at
    ),

  constraint
    task_recurrence_rules_last_valid
    check (
      last_occurrence_at is null
      or last_occurrence_at >=
        start_at
    )
);


create index if not exists
  task_recurrence_rules_workspace_idx
on public.task_recurrence_rules (
  workspace_id,
  created_at desc
);


create index if not exists
  task_recurrence_rules_due_idx
on public.task_recurrence_rules (
  is_enabled,
  next_occurrence_at
)
where is_enabled = true;


-- ============================================================
-- LINK GENERATED TASKS TO THEIR RULE
-- ============================================================

alter table public.tasks
  add column if not exists
    recurrence_rule_id uuid;


alter table public.tasks
  add column if not exists
    recurrence_occurrence_at
      timestamptz;


do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where
      conrelid =
        'public.tasks'::regclass
      and conname =
        'tasks_recurrence_rule_id_fkey'
  ) then
    alter table public.tasks
      add constraint
        tasks_recurrence_rule_id_fkey
      foreign key (
        recurrence_rule_id
      )
      references
        public.task_recurrence_rules(id)
      on delete set null;
  end if;
end
$$;


do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where
      conrelid =
        'public.task_recurrence_rules'::regclass
      and conname =
        'task_recurrence_rules_template_task_id_fkey'
  ) then
    alter table
      public.task_recurrence_rules
      add constraint
        task_recurrence_rules_template_task_id_fkey
      foreign key (
        template_task_id
      )
      references public.tasks(id)
      on delete set null;
  end if;
end
$$;


create unique index if not exists
  tasks_recurrence_occurrence_unique
on public.tasks (
  recurrence_rule_id,
  recurrence_occurrence_at
)
where
  recurrence_rule_id is not null
  and recurrence_occurrence_at
    is not null;


create index if not exists
  tasks_recurrence_rule_idx
on public.tasks (
  recurrence_rule_id,
  recurrence_occurrence_at
);


-- ============================================================
-- ADVANCE RECURRENCE
--
-- Preserves the selected local clock time through DST by
-- converting into the recurrence timezone before adding the
-- interval and converting back to timestamptz.
-- ============================================================

create or replace function
public.advance_task_recurrence_occurrence(
  p_current timestamptz,
  p_unit text,
  p_interval_count integer,
  p_timezone text
)
returns timestamptz
language plpgsql
stable
set search_path =
  pg_catalog,
  public
as $$
declare
  local_current timestamp;
  local_next timestamp;
begin
  if p_current is null then
    raise exception
      'Current recurrence time is required.';
  end if;

  if p_interval_count is null
     or p_interval_count < 1
     or p_interval_count > 365
  then
    raise exception
      'Recurrence interval must be between 1 and 365.';
  end if;

  if p_unit not in (
    'day',
    'week',
    'month'
  ) then
    raise exception
      'Unsupported recurrence unit: %',
      p_unit;
  end if;

  if not exists (
    select 1
    from pg_catalog.pg_timezone_names
    where name = p_timezone
  ) then
    raise exception
      'Unknown recurrence timezone: %',
      p_timezone;
  end if;

  local_current :=
    p_current
      at time zone p_timezone;

  local_next :=
    case p_unit
      when 'day' then
        local_current
        + pg_catalog.make_interval(
            days =>
              p_interval_count
          )

      when 'week' then
        local_current
        + pg_catalog.make_interval(
            days =>
              p_interval_count * 7
          )

      when 'month' then
        local_current
        + pg_catalog.make_interval(
            months =>
              p_interval_count
          )
    end;

  return
    local_next
      at time zone p_timezone;
end;
$$;


revoke all
on function
  public.advance_task_recurrence_occurrence(
    timestamptz,
    text,
    integer,
    text
  )
from public;


revoke all
on function
  public.advance_task_recurrence_occurrence(
    timestamptz,
    text,
    integer,
    text
  )
from anon;


revoke all
on function
  public.advance_task_recurrence_occurrence(
    timestamptz,
    text,
    integer,
    text
  )
from authenticated;


-- ============================================================
-- NORMALIZE / PROTECT RULES
-- ============================================================

create or replace function
public.normalize_task_recurrence_rule()
returns trigger
language plpgsql
security invoker
set search_path =
  pg_catalog,
  public
as $$
begin
  if tg_op = 'UPDATE' then
    if
      new.workspace_id
        is distinct from
          old.workspace_id
      or new.created_by
        is distinct from
          old.created_by
      or new.template_task_id
        is distinct from
          old.template_task_id
    then
      raise exception
        'Recurrence ownership and template are immutable.';
    end if;
  end if;

  if not exists (
    select 1
    from pg_catalog.pg_timezone_names
    where name =
      new.schedule_timezone
  ) then
    raise exception
      'Unknown recurrence timezone: %',
      new.schedule_timezone;
  end if;

  new.title :=
    btrim(new.title);

  new.description :=
    nullif(
      btrim(
        coalesce(
          new.description,
          ''
        )
      ),
      ''
    );

  new.category :=
    coalesce(
      nullif(
        btrim(new.category),
        ''
      ),
      'General'
    );

  new.priority :=
    coalesce(
      nullif(
        btrim(new.priority),
        ''
      ),
      'normal'
    );

  new.visibility :=
    coalesce(
      nullif(
        btrim(new.visibility),
        ''
      ),
      'workspace'
    );

  new.tags :=
    coalesce(
      new.tags,
      '{}'::text[]
    );

  new.checklist_template :=
    coalesce(
      new.checklist_template,
      '[]'::jsonb
    );

  new.updated_at :=
    now();

  return new;
end;
$$;


drop trigger if exists
  normalize_task_recurrence_rule_trigger
on public.task_recurrence_rules;


create trigger
  normalize_task_recurrence_rule_trigger
before insert or update
on public.task_recurrence_rules
for each row
execute function
  public.normalize_task_recurrence_rule();


