enable row level security;


drop policy if exists
  "Visible task recurrence rules can be viewed"
on public.task_recurrence_rules;


create policy
  "Visible task recurrence rules can be viewed"
on public.task_recurrence_rules
for select
to authenticated
using (
  (
    template_task_id is not null

    and public.can_view_role_scoped_task(
      template_task_id
    )
  )

  or (
    template_task_id is null

    and public.is_workspace_member(
      workspace_id
    )

    and (
      public.is_workspace_admin(
        workspace_id
      )

      or public.has_campaign_permission(
        workspace_id,
        'tasks.manage_all'
      )

      or created_by =
        auth.uid()

      or assigned_to =
        auth.uid()
    )
  )
);


