  "Authorized members can create task recurrence rules"
on public.task_recurrence_rules;


create policy
  "Authorized members can create task recurrence rules"
on public.task_recurrence_rules
for insert
to authenticated
with check (
  created_by = auth.uid()

  and public.is_workspace_member(
    workspace_id
  )

  and (
    public.is_workspace_admin(
      workspace_id
    )

    or public.has_campaign_permission(
      workspace_id,
