-- ============================================================
-- CREATE RECURRENCE FROM AN EXISTING TASK
--
-- The existing task becomes occurrence #1.
-- Future recurrence starts AFTER its current deadline.
-- ============================================================

create or replace function
public.create_task_recurrence_from_task(
  p_task_id uuid,
  p_recurrence_unit text,
  p_interval_count integer
    default 1,
  p_end_at timestamptz
    default null,
  p_schedule_timezone text
    default 'America/New_York'
)
returns public.task_recurrence_rules
language plpgsql
security definer
set search_path =
  pg_catalog,
  public
as $$
declare
  task_record public.tasks%rowtype;

  created_rule
    public.task_recurrence_rules%rowtype;

  checklist_snapshot jsonb;

  next_time timestamptz;

  guard integer := 0;
begin
  if auth.uid() is null then
    raise exception
      'Authentication required.';
  end if;

  select *
  into task_record
  from public.tasks
  where id = p_task_id
  for update;

  if not found then
    raise exception
      'Task not found.';
  end if;

  if not
    public.can_view_role_scoped_task(
      task_record.id
    )
  then
    raise exception
      'Task is not accessible.';
  end if;

  if not (
    public.is_workspace_admin(
      task_record.workspace_id
    )

    or public.has_campaign_permission(
      task_record.workspace_id,
      'tasks.manage_all'
    )

    or task_record.created_by =
      auth.uid()

    or task_record.assigned_to =
      auth.uid()
  ) then
    raise exception
      'You cannot configure recurrence for this task.';
  end if;

  if task_record.recurrence_rule_id
       is not null
  then
    raise exception
      'Task already belongs to a recurrence.';
  end if;

  if task_record.due_at is null then
    raise exception
      'Recurring tasks require a deadline.';
  end if;

  if p_recurrence_unit not in (
    'day',
    'week',
    'month'
  ) then
    raise exception
      'Unsupported recurrence unit.';
  end if;

  if p_interval_count is null
     or p_interval_count < 1
     or p_interval_count > 365
  then
    raise exception
      'Recurrence interval must be between 1 and 365.';
  end if;

  if p_end_at is not null
     and p_end_at <=
       task_record.due_at
  then
    raise exception
      'Recurrence end must be after the first task deadline.';
  end if;

  -- Validates timezone while calculating
  -- the first future occurrence.
  next_time :=
    public.advance_task_recurrence_occurrence(
      task_record.due_at,
      p_recurrence_unit,
      p_interval_count,
      p_schedule_timezone
    );

  -- If recurrence is being attached to an older task,
  -- skip historical missed occurrences instead of
  -- creating a backlog.
  while next_time <= now() loop
    guard := guard + 1;

    if guard > 10000 then
      raise exception
        'Recurrence schedule could not be advanced safely.';
    end if;

    next_time :=
      public.advance_task_recurrence_occurrence(
        next_time,
        p_recurrence_unit,
        p_interval_count,
        p_schedule_timezone
      );
  end loop;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'title',
          subtask.title
        )
        order by
          subtask.sort_order,
          subtask.created_at,
          subtask.id
      ),
      '[]'::jsonb
    )
  into checklist_snapshot
  from public.task_subtasks
    as subtask
  where
    subtask.task_id =
      task_record.id
    and subtask.workspace_id =
      task_record.workspace_id;

  insert into
    public.task_recurrence_rules (
      workspace_id,
      created_by,
      template_task_id,

      title,
      description,
      category,
      priority,
      visibility,
      tags,
      estimated_minutes,
      assigned_to,

      checklist_template,

      recurrence_unit,
      interval_count,
      schedule_timezone,

      start_at,
      end_at,

      next_occurrence_at,
      last_occurrence_at,

      is_enabled
    )
  values (
    task_record.workspace_id,
    task_record.created_by,
    task_record.id,

    task_record.title,
    task_record.description,
    coalesce(
      task_record.category,
      'General'
    ),
    coalesce(
      task_record.priority,
      'normal'
    ),
    coalesce(
      task_record.visibility,
      'workspace'
    ),
    coalesce(
      task_record.tags,
      '{}'::text[]
    ),
    task_record.estimated_minutes,
    task_record.assigned_to,

    checklist_snapshot,

    p_recurrence_unit,
    p_interval_count,
    p_schedule_timezone,

    task_record.due_at,
    p_end_at,

    next_time,
    task_record.due_at,

    case
      when
        p_end_at is not null
        and next_time > p_end_at
      then false
      else true
    end
  )
  returning *
  into created_rule;

  update public.tasks
  set
    recurrence_rule_id =
      created_rule.id,

    recurrence_occurrence_at =
      task_record.due_at,

    updated_at =
      now()
  where id =
    task_record.id;

  return created_rule;
end;
$$;


revoke all
on function
  public.create_task_recurrence_from_task(
    uuid,
    text,
    integer,
    timestamptz,
    text
  )
from public;


revoke all
