-- ============================================================
-- PAUSE / RESUME
--
-- Resume skips occurrences missed while paused.
-- ============================================================

create or replace function
public.set_task_recurrence_enabled(
  p_rule_id uuid,
  p_enabled boolean
)
returns public.task_recurrence_rules
language plpgsql
security definer
set search_path =
  pg_catalog,
  public
as $$
declare
  recurrence
    public.task_recurrence_rules%rowtype;

  next_time timestamptz;

  guard integer := 0;
begin
  if auth.uid() is null then
    raise exception
      'Authentication required.';
  end if;

  select *
  into recurrence
  from public.task_recurrence_rules
  where id = p_rule_id
  for update;

  if not found then
    raise exception
      'Recurrence rule not found.';
  end if;

  if not (
    public.is_workspace_admin(
      recurrence.workspace_id
    )

    or public.has_campaign_permission(
      recurrence.workspace_id,
      'tasks.manage_all'
    )

    or recurrence.created_by =
      auth.uid()

    or recurrence.assigned_to =
      auth.uid()
  ) then
    raise exception
      'You cannot change this recurrence.';
  end if;

  if not p_enabled then
    update
      public.task_recurrence_rules
    set
      is_enabled = false,
      updated_at = now()
    where id =
      recurrence.id
    returning *
    into recurrence;

    return recurrence;
  end if;

  next_time :=
    recurrence.next_occurrence_at;

  while next_time <= now() loop
    guard := guard + 1;

    if guard > 10000 then
      raise exception
        'Recurrence schedule could not be resumed safely.';
    end if;

    next_time :=
      public.advance_task_recurrence_occurrence(
        next_time,
        recurrence.recurrence_unit,
        recurrence.interval_count,
        recurrence.schedule_timezone
      );
  end loop;

  update
    public.task_recurrence_rules
  set
    next_occurrence_at =
      next_time,

    is_enabled =
      case
        when
          recurrence.end_at is not null
          and next_time >
            recurrence.end_at
        then false
        else true
      end,

    updated_at =
      now()
  where id =
    recurrence.id
  returning *
  into recurrence;

  return recurrence;
end;
$$;


revoke all
on function
  public.set_task_recurrence_enabled(
    uuid,
    boolean
  )
from public;


revoke all
on function
  public.set_task_recurrence_enabled(
    uuid,
    boolean
  )
from anon;


grant execute
on function
  public.set_task_recurrence_enabled(
    uuid,
    boolean
  )
to authenticated;


-- ============================================================
-- PROCESS RECURRENCES
-- ============================================================

create or replace function
public.process_task_recurrences()
returns integer
language plpgsql
security definer
set search_path =
  pg_catalog,
  public
as $$
declare
  recurrence
    public.task_recurrence_rules%rowtype;

  generated_task_id uuid;

  occurrence_time timestamptz;

  generated_for_rule integer;

  total_generated integer := 0;
begin
  -- Never allow overlapping recurrence processors.
  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'campaign-seat-task-recurrences',
      0
    )
  );

  for recurrence in
    select *
    from public.task_recurrence_rules
    where
      is_enabled = true
      and next_occurrence_at <=
        now()
      and (
        end_at is null
        or next_occurrence_at <=
          end_at
      )
    order by
      next_occurrence_at asc
    for update skip locked
  loop
    generated_for_rule := 0;

    while
      recurrence.next_occurrence_at <=
        now()

      and (
        recurrence.end_at is null
        or recurrence.next_occurrence_at <=
          recurrence.end_at
      )

      and generated_for_rule < 25
    loop
      occurrence_time :=
        recurrence.next_occurrence_at;

      generated_task_id :=
        null;

      insert into public.tasks (
        workspace_id,
        created_by,

        title,
        description,
        category,
        priority,
        visibility,
        tags,
        estimated_minutes,
        due_at,
        assigned_to,

        status,
        is_sample,

        recurrence_rule_id,
        recurrence_occurrence_at
      )
      values (
        recurrence.workspace_id,
        recurrence.created_by,

        recurrence.title,
        recurrence.description,
        recurrence.category,
        recurrence.priority,
        recurrence.visibility,
        recurrence.tags,
        recurrence.estimated_minutes,
        occurrence_time,
        recurrence.assigned_to,

        'open',
        false,

        recurrence.id,
        occurrence_time
      )
      on conflict (
        recurrence_rule_id,
        recurrence_occurrence_at
      )
      where
        recurrence_rule_id is not null
        and recurrence_occurrence_at
          is not null
      do nothing
      returning id
      into generated_task_id;

      if generated_task_id
           is not null
      then
        insert into
          public.task_subtasks (
            workspace_id,
            task_id,
            title,
            is_completed,
            sort_order,
            created_by
          )
        select
          recurrence.workspace_id,
          generated_task_id,

          btrim(
            checklist_item.value
              ->> 'title'
          ),

          false,

          (
            checklist_item.ordinality
            - 1
          )::integer,

          recurrence.created_by
        from
          jsonb_array_elements(
            recurrence.checklist_template
          )
          with ordinality
          as checklist_item(
            value,
            ordinality
          )
        where
          nullif(
            btrim(
              checklist_item.value
                ->> 'title'
            ),
            ''
          ) is not null;

        total_generated :=
          total_generated + 1;
      end if;

      recurrence.last_occurrence_at :=
        occurrence_time;

      recurrence.next_occurrence_at :=
        public.advance_task_recurrence_occurrence(
          occurrence_time,
          recurrence.recurrence_unit,
          recurrence.interval_count,
          recurrence.schedule_timezone
        );

      update
        public.task_recurrence_rules
      set
        last_occurrence_at =
          recurrence.last_occurrence_at,

        next_occurrence_at =
          recurrence.next_occurrence_at,

        is_enabled =
          case
            when
              recurrence.end_at
                is not null
              and
              recurrence.next_occurrence_at >
                recurrence.end_at
            then false
            else is_enabled
          end,

        updated_at =
          now()
      where id =
        recurrence.id;

      generated_for_rule :=
        generated_for_rule + 1;
    end loop;

    if
      recurrence.end_at is not null
      and recurrence.next_occurrence_at >
        recurrence.end_at
    then
      update
        public.task_recurrence_rules
      set
        is_enabled = false,
        updated_at = now()
      where id =
        recurrence.id;
    end if;
  end loop;

  return total_generated;
end;
$$;


revoke all
on function
  public.process_task_recurrences()
from public;


revoke all
on function
  public.process_task_recurrences()
from anon;


revoke all
on function
  public.process_task_recurrences()
from authenticated;


-- ============================================================
-- CRON
-- ============================================================

do $$
declare
  existing_job record;
begin
  for existing_job in
    select jobid
    from cron.job
    where jobname =
      'campaign-seat-task-recurrences'
  loop
    perform cron.unschedule(
      existing_job.jobid
    );
  end loop;
end
$$;


select cron.schedule(
  'campaign-seat-task-recurrences',
  '* * * * *',
  $cron$
    select
      public.process_task_recurrences();
  $cron$
);


