comment on table
  public.task_recurrence_rules
is
  'Recurring task templates and schedules. Existing generated tasks remain independent historical occurrences.';


comment on column
  public.tasks.recurrence_rule_id
is
  'Recurring task rule that generated or owns this task occurrence.';


comment on column
  public.tasks.recurrence_occurrence_at
is
  'Scheduled occurrence timestamp used for recurring-task idempotency.';
